-- Seed data: all 78 Rider-Waite tarot cards.
-- id 1-22  = Major Arcana (The Fool 0 -> The World XXI)
-- id 23-36 = Wands, 37-50 = Cups, 51-64 = Swords, 65-78 = Pentacles
-- image_ref points to bundled public-domain Rider-Waite assets (rws/{key}.jpg).
-- fallback_reading_* is the static daily reading used when the AI content
-- cache misses (degraded mode) and must stand alone without extra context.

insert into public.tarot_cards
    (id, key, name_vi, name_en,
     upright_meaning_vi, upright_meaning_en,
     reversed_meaning_vi, reversed_meaning_en,
     fallback_reading_vi, fallback_reading_en,
     image_ref)
values
(1, 'the_fool', 'Chàng Khờ', 'The Fool',
 'Khởi đầu mới, tinh thần tự do và niềm tin hồn nhiên vào cuộc sống. Bạn được mời gọi dấn thân vào một hành trình mới với trái tim rộng mở.',
 'New beginnings, free spirit, and innocent trust in life. You are invited to take a leap of faith into an unknown journey.',
 'Sự liều lĩnh thiếu suy nghĩ, ngây thơ quá mức, hoặc nỗi sợ khiến bạn chần chừ không dám bắt đầu.',
 'Recklessness, naivety, or a fear of the unknown that keeps you from taking the first step.',
 'Hôm nay, Chàng Khờ mời bạn nhìn cuộc sống bằng ánh mắt mới mẻ. Có thể một cơ hội đang chờ bạn đủ can đảm để bước tới. Hãy tin vào trực giác và cho phép mình bắt đầu, dù con đường phía trước chưa hoàn toàn rõ ràng.',
 'Today, The Fool invites you to see life with fresh eyes. An opportunity may be waiting for you to take one brave step forward. Trust your instincts and allow yourself to begin, even before the whole path is clear.',
 'rws/the_fool.jpg'),
(2, 'the_magician', 'Nhà Ảo Thuật', 'The Magician',
 'Ý chí, sự khéo léo và khả năng biến ý tưởng thành hiện thực. Mọi công cụ bạn cần đều đã nằm trong tay bạn.',
 'Willpower, skill, and the ability to turn ideas into reality. Every tool you need is already in your hands.',
 'Tài năng bị lãng phí, sự thao túng, hoặc cảm giác thiếu tự tin vào năng lực của chính mình.',
 'Wasted talent, manipulation, or a lack of confidence in your own abilities.',
 'Nhà Ảo Thuật nhắc bạn rằng bạn có nhiều nguồn lực hơn mình tưởng. Hôm nay, hãy chọn một mục tiêu nhỏ và dồn sự tập trung của bạn vào đó. Khi ý chí và hành động gặp nhau, những điều tưởng như khó khăn sẽ bắt đầu chuyển động.',
 'The Magician reminds you that you have more resources than you realize. Today, pick one small goal and give it your full focus. When willpower meets action, things that seemed difficult begin to move.',
 'rws/the_magician.jpg'),
(3, 'the_high_priestess', 'Nữ Tư Tế', 'The High Priestess',
 'Trực giác, sự tĩnh lặng nội tâm và những hiểu biết sâu sắc chưa được nói thành lời. Câu trả lời nằm ở bên trong bạn.',
 'Intuition, inner stillness, and deep knowing that has not yet been spoken. The answer lies within you.',
 'Bỏ qua tiếng nói bên trong, những bí mật bị che giấu, hoặc sự mất kết nối với chính mình.',
 'Ignoring your inner voice, hidden secrets, or feeling disconnected from yourself.',
 'Nữ Tư Tế mời bạn chậm lại và lắng nghe. Hôm nay, thay vì vội tìm câu trả lời bên ngoài, hãy dành vài phút yên tĩnh với chính mình. Trực giác của bạn đang cố nói với bạn điều gì đó quan trọng.',
 'The High Priestess invites you to slow down and listen. Today, instead of rushing to find answers outside, spend a few quiet minutes with yourself. Your intuition is trying to tell you something important.',
 'rws/the_high_priestess.jpg'),
(4, 'the_empress', 'Nữ Hoàng', 'The Empress',
 'Sự nuôi dưỡng, sung túc và sáng tạo dồi dào. Đây là thời điểm để chăm sóc bản thân và những gì bạn đang vun trồng.',
 'Nurturing, abundance, and flowing creativity. This is a time to care for yourself and for what you are growing.',
 'Sự phụ thuộc, bao bọc quá mức, hoặc quên chăm sóc chính mình trong khi lo cho người khác.',
 'Dependence, smothering, or neglecting your own needs while caring for others.',
 'Nữ Hoàng nhắc bạn rằng mọi thứ đẹp đẽ đều cần thời gian để lớn lên. Hôm nay, hãy đối xử dịu dàng với bản thân như cách bạn chăm sóc một khu vườn. Một bữa ăn ngon, một giấc ngủ đủ, một lời tử tế — những điều nhỏ ấy đang nuôi dưỡng bạn.',
 'The Empress reminds you that beautiful things take time to grow. Today, treat yourself as gently as you would tend a garden. A good meal, enough rest, a kind word — these small things are nourishing you.',
 'rws/the_empress.jpg'),
(5, 'the_emperor', 'Hoàng Đế', 'The Emperor',
 'Sự vững vàng, kỷ luật và khả năng làm chủ hoàn cảnh. Cấu trúc và trật tự sẽ mang lại cho bạn cảm giác an toàn.',
 'Stability, discipline, and mastery over your circumstances. Structure and order bring you a sense of safety.',
 'Sự cứng nhắc, kiểm soát thái quá, hoặc lạm dụng quyền lực khiến các mối quan hệ trở nên căng thẳng.',
 'Rigidity, excessive control, or misuse of authority that strains relationships.',
 'Hoàng Đế mời bạn xây dựng nền móng vững chắc cho điều bạn mong muốn. Hôm nay, một chút kỷ luật — dù chỉ là sắp xếp lại lịch trình hay hoàn thành một việc đã trì hoãn — sẽ cho bạn cảm giác làm chủ. Sự vững vàng bắt đầu từ những thói quen nhỏ.',
 'The Emperor invites you to build solid foundations for what you want. Today, a little discipline — even just organizing your schedule or finishing one postponed task — will give you a sense of command. Stability begins with small habits.',
 'rws/the_emperor.jpg'),
(6, 'the_hierophant', 'Giáo Hoàng', 'The Hierophant',
 'Truyền thống, sự học hỏi và những giá trị được truyền lại. Một người thầy hoặc con đường đã được kiểm chứng có thể dẫn lối cho bạn.',
 'Tradition, learning, and values passed down through time. A mentor or a proven path may guide you now.',
 'Sự gò bó bởi khuôn mẫu, nổi loạn chống lại quy tắc, hoặc nhu cầu tìm ra con đường riêng của mình.',
 'Feeling confined by convention, rebelling against rules, or needing to find your own path.',
 'Giáo Hoàng nhắc bạn rằng không phải bài học nào cũng cần tự mình trải qua. Hôm nay, hãy để ý những lời khuyên từ người đi trước hoặc những giá trị đã bền vững theo thời gian. Đôi khi sự khôn ngoan nằm ở việc biết lắng nghe.',
 'The Hierophant reminds you that not every lesson must be learned the hard way. Today, pay attention to advice from those who came before you, or to values that have stood the test of time. Sometimes wisdom lies in knowing how to listen.',
 'rws/the_hierophant.jpg'),
(7, 'the_lovers', 'Đôi Tình Nhân', 'The Lovers',
 'Tình yêu, sự hòa hợp và những lựa chọn xuất phát từ trái tim. Một mối kết nối sâu sắc hoặc một quyết định quan trọng đang chờ bạn.',
 'Love, harmony, and choices made from the heart. A deep connection or an important decision awaits you.',
 'Sự bất hòa, giá trị lệch nhau, hoặc một lựa chọn khó khăn mà bạn đang né tránh.',
 'Disharmony, misaligned values, or a difficult choice you have been avoiding.',
 'Đôi Tình Nhân nói về sự lựa chọn và kết nối. Hôm nay, hãy tự hỏi: điều gì thực sự quan trọng với trái tim bạn? Khi bạn sống đúng với giá trị của mình, các mối quan hệ xung quanh cũng trở nên chân thật và ấm áp hơn.',
 'The Lovers speak of choice and connection. Today, ask yourself: what truly matters to your heart? When you live in line with your values, the relationships around you become more honest and warm.',
 'rws/the_lovers.jpg'),
(8, 'the_chariot', 'Cỗ Xe', 'The Chariot',
 'Ý chí chiến thắng, sự quyết tâm và khả năng làm chủ những lực kéo trái chiều. Bạn đang tiến về phía trước bằng chính nội lực của mình.',
 'Willpower, determination, and mastery over opposing forces. You are moving forward through your own inner strength.',
 'Mất phương hướng, thiếu kiểm soát, hoặc sự hung hăng che giấu cảm giác bất lực bên trong.',
 'Lack of direction, loss of control, or aggression masking a feeling of powerlessness within.',
 'Cỗ Xe mời bạn nắm chắc dây cương của ngày hôm nay. Có thể nhiều việc đang kéo bạn về những hướng khác nhau, nhưng bạn có đủ ý chí để giữ vững lộ trình. Hãy chọn một đích đến rõ ràng và tiến về phía đó, từng bước một.',
 'The Chariot invites you to take firm hold of today''s reins. Many things may be pulling you in different directions, but you have the will to stay on course. Choose one clear destination and move toward it, step by step.',
 'rws/the_chariot.jpg'),
(9, 'strength', 'Sức Mạnh', 'Strength',
 'Lòng can đảm dịu dàng, sự kiên nhẫn và sức mạnh nội tâm. Bạn thuần phục khó khăn bằng sự bao dung chứ không phải vũ lực.',
 'Gentle courage, patience, and inner strength. You tame difficulty with compassion rather than force.',
 'Sự nghi ngờ bản thân, mất tự tin, hoặc để cảm xúc bốc đồng lấn át lý trí.',
 'Self-doubt, loss of confidence, or letting raw impulses overpower your better judgment.',
 'Sức Mạnh nhắc bạn rằng can đảm không phải lúc nào cũng ồn ào. Hôm nay, sự dịu dàng với chính mình và với người khác chính là biểu hiện cao nhất của nội lực. Bạn mạnh mẽ hơn những gì thử thách này khiến bạn cảm thấy.',
 'Strength reminds you that courage is not always loud. Today, gentleness toward yourself and others is the highest form of inner power. You are stronger than this challenge makes you feel.',
 'rws/strength.jpg'),
(10, 'the_hermit', 'Ẩn Sĩ', 'The Hermit',
 'Sự chiêm nghiệm, tìm kiếm chân lý bên trong và khoảng lặng cần thiết. Ánh sáng bạn tìm kiếm nằm trong chính sự tĩnh tại.',
 'Introspection, the search for inner truth, and necessary solitude. The light you seek is found in stillness.',
 'Sự cô lập kéo dài, né tránh người khác, hoặc cảm giác lạc lõng vì đã quay lưng với thế giới quá lâu.',
 'Prolonged isolation, withdrawing from others, or feeling lost after turning away from the world for too long.',
 'Ẩn Sĩ mời bạn dành cho mình một khoảng lặng hôm nay. Giữa nhịp sống vội vã, vài phút một mình — không màn hình, không tiếng ồn — có thể soi sáng điều bạn đang trăn trở. Câu trả lời thường đến khi ta đủ yên để nghe thấy nó.',
 'The Hermit invites you to give yourself a quiet moment today. Amid the rush of life, a few minutes alone — no screens, no noise — can illuminate what has been weighing on you. Answers often arrive when we are still enough to hear them.',
 'rws/the_hermit.jpg'),
(11, 'wheel_of_fortune', 'Vòng Quay May Mắn', 'Wheel of Fortune',
 'Bước ngoặt, chu kỳ thay đổi và vận may đang xoay chuyển. Cuộc sống đang mở ra một chương mới cho bạn.',
 'A turning point, cycles of change, and fortune in motion. Life is opening a new chapter for you.',
 'Vận rủi tạm thời, cảm giác mọi thứ ngoài tầm kiểm soát, hoặc kháng cự lại sự thay đổi tất yếu.',
 'A streak of bad luck, feeling that things are out of your control, or resisting inevitable change.',
 'Vòng Quay May Mắn nhắc bạn rằng không có điều gì đứng yên mãi — kể cả khó khăn. Hôm nay, hãy để ý những cánh cửa nhỏ đang hé mở quanh bạn. Điều bạn có thể làm là giữ lòng cởi mở và sẵn sàng khi thời cơ xoay đến.',
 'The Wheel of Fortune reminds you that nothing stays still forever — not even hardship. Today, notice the small doors quietly opening around you. What you can do is stay open and ready as the wheel turns your way.',
 'rws/wheel_of_fortune.jpg'),
(12, 'justice', 'Công Lý', 'Justice',
 'Sự công bằng, chân thật và trách nhiệm với lựa chọn của mình. Nhân quả đang vận hành và sự thật sẽ được sáng tỏ.',
 'Fairness, truth, and accountability for your choices. Cause and effect are at work, and the truth will come to light.',
 'Sự bất công, thiếu trung thực với bản thân, hoặc né tránh hậu quả từ quyết định của mình.',
 'Injustice, dishonesty with yourself, or avoiding the consequences of your decisions.',
 'Công Lý mời bạn nhìn mọi việc hôm nay một cách khách quan và trung thực. Trước khi phán xét người khác hay chính mình, hãy cân nhắc cả hai mặt của câu chuyện. Sự công tâm bạn trao đi hôm nay sẽ quay về với bạn.',
 'Justice invites you to see today''s events with clear and honest eyes. Before judging others or yourself, weigh both sides of the story. The fairness you offer today will find its way back to you.',
 'rws/justice.jpg'),
(13, 'the_hanged_man', 'Người Treo Ngược', 'The Hanged Man',
 'Sự buông bỏ, thay đổi góc nhìn và trí tuệ đến từ việc tạm dừng. Đôi khi không làm gì lại chính là bước tiến lớn nhất.',
 'Surrender, a shift in perspective, and wisdom gained through pause. Sometimes doing nothing is the greatest step forward.',
 'Sự trì hoãn vô ích, hy sinh không được ghi nhận, hoặc mắc kẹt vì không chịu nhìn khác đi.',
 'Pointless delay, unappreciated sacrifice, or feeling stuck because you refuse to see things differently.',
 'Người Treo Ngược mời bạn thử nhìn vấn đề từ một góc hoàn toàn khác. Điều đang khiến bạn bế tắc có thể chỉ cần một cách nhìn mới thay vì một hành động mới. Hôm nay, hãy cho phép mình tạm dừng mà không cảm thấy có lỗi.',
 'The Hanged Man invites you to look at your situation from an entirely new angle. What feels stuck may need a fresh perspective rather than more effort. Today, give yourself permission to pause without guilt.',
 'rws/the_hanged_man.jpg'),
(14, 'death', 'Thần Chết', 'Death',
 'Sự kết thúc cần thiết để mở ra khởi đầu mới. Một giai đoạn đang khép lại để bạn được chuyển hóa và tái sinh.',
 'A necessary ending that makes way for a new beginning. A chapter is closing so you can transform and be reborn.',
 'Sự níu kéo những gì đã hết vai trò, sợ thay đổi, hoặc quá trình chuyển hóa đang bị trì hoãn.',
 'Clinging to what has run its course, fear of change, or a transformation being delayed.',
 'Thần Chết không nói về mất mát, mà về sự chuyển hóa. Hôm nay, hãy tự hỏi: điều gì trong cuộc sống của bạn đã hoàn thành vai trò của nó? Khi bạn dám khép lại một cánh cửa cũ, không gian cho điều mới mẻ sẽ tự nhiên xuất hiện.',
 'Death speaks not of loss but of transformation. Today, ask yourself: what in your life has served its purpose? When you dare to close an old door, space for something new naturally appears.',
 'rws/death.jpg'),
(15, 'temperance', 'Sự Điều Độ', 'Temperance',
 'Sự cân bằng, kiên nhẫn và hòa hợp giữa các thái cực. Con đường trung dung đang mang lại cho bạn sự bình an.',
 'Balance, patience, and harmony between extremes. The middle path is bringing you peace.',
 'Sự mất cân bằng, quá đà, hoặc thiếu kiên nhẫn khiến mọi thứ trở nên chệch nhịp.',
 'Imbalance, excess, or impatience throwing things out of rhythm.',
 'Sự Điều Độ mời bạn tìm lại nhịp cân bằng của mình. Hôm nay, hãy để ý xem mình đang nghiêng quá nhiều về phía nào — công việc hay nghỉ ngơi, cho đi hay giữ lại. Một điều chỉnh nhỏ, thực hiện với sự kiên nhẫn, sẽ đưa mọi thứ về đúng nhịp.',
 'Temperance invites you to find your balance again. Today, notice where you may be leaning too far — work or rest, giving or holding back. One small adjustment, made with patience, will bring things back into rhythm.',
 'rws/temperance.jpg'),
(16, 'the_devil', 'Ác Quỷ', 'The Devil',
 'Sự ràng buộc, cám dỗ và những khuôn mẫu đang giam giữ bạn. Sợi xích trói buộc thường lỏng hơn bạn nghĩ.',
 'Bondage, temptation, and patterns that hold you captive. The chains that bind you are often looser than they appear.',
 'Sự thức tỉnh, giải phóng khỏi thói quen độc hại, hoặc bước đầu lấy lại quyền làm chủ chính mình.',
 'Awakening, breaking free from unhealthy patterns, or beginning to reclaim your own power.',
 'Ác Quỷ mời bạn nhìn thẳng vào điều đang âm thầm trói buộc mình — một thói quen, một nỗi sợ, hay một suy nghĩ lặp đi lặp lại. Nhận diện nó chính là bước đầu tiên của tự do. Hôm nay, bạn có nhiều quyền lựa chọn hơn bạn tưởng.',
 'The Devil invites you to look honestly at what quietly binds you — a habit, a fear, or a repeating thought. Naming it is the first act of freedom. Today, you have more choices than you think.',
 'rws/the_devil.jpg'),
(17, 'the_tower', 'Tòa Tháp', 'The Tower',
 'Sự sụp đổ đột ngột của những gì được xây trên nền móng không vững. Cú sốc hôm nay dọn đường cho sự thật và tái thiết.',
 'The sudden collapse of what was built on shaky foundations. Today''s upheaval clears the way for truth and rebuilding.',
 'Né tránh một sự thay đổi tất yếu, khủng hoảng kéo dài, hoặc nỗi sợ sụp đổ khiến bạn không dám xây mới.',
 'Avoiding an inevitable change, a prolonged crisis, or fear of collapse keeping you from building anew.',
 'Tòa Tháp nhắc rằng đôi khi những gì lung lay cần được buông để bạn xây lại vững chắc hơn. Nếu hôm nay có điều gì xáo trộn, hãy nhớ: cái cũ sụp xuống để lộ ra nền móng thật. Bạn có khả năng dựng lại, lần này bền vững hơn.',
 'The Tower reminds you that what is unstable sometimes needs to fall so you can rebuild on solid ground. If something shakes today, remember: the collapse reveals the true foundation. You are capable of rebuilding, stronger this time.',
 'rws/the_tower.jpg'),
(18, 'the_star', 'Ngôi Sao', 'The Star',
 'Hy vọng, sự chữa lành và niềm tin được thắp sáng trở lại. Sau cơn bão, bầu trời của bạn đang dần trong xanh.',
 'Hope, healing, and renewed faith. After the storm, your sky is clearing.',
 'Sự mất niềm tin, chán nản, hoặc quên mất rằng ánh sáng vẫn luôn ở đó dù bị mây che.',
 'Loss of faith, discouragement, or forgetting that the light is still there behind the clouds.',
 'Ngôi Sao mang đến thông điệp của hy vọng và chữa lành. Dù gần đây có điều gì khiến bạn mệt mỏi, hôm nay là ngày để tin rằng mọi thứ đang dần tốt lên. Hãy làm một điều nhỏ nuôi dưỡng tâm hồn mình — bạn xứng đáng với sự dịu dàng đó.',
 'The Star carries a message of hope and healing. Whatever has wearied you lately, today is a day to trust that things are slowly getting better. Do one small thing that nourishes your soul — you deserve that gentleness.',
 'rws/the_star.jpg'),
(19, 'the_moon', 'Mặt Trăng', 'The Moon',
 'Trực giác, những giấc mơ và vùng mờ ảo giữa thực và tưởng. Không phải điều gì bạn sợ cũng có thật.',
 'Intuition, dreams, and the misty space between what is real and imagined. Not everything you fear is true.',
 'Sự thật dần sáng tỏ, nỗi lo âu được giải tỏa, hoặc thoát ra khỏi những ảo tưởng đã che mắt bạn.',
 'Truth coming to light, anxiety easing, or emerging from illusions that clouded your vision.',
 'Mặt Trăng nhắc bạn rằng trong ánh sáng mờ ảo, mọi thứ có thể trông đáng sợ hơn thực tế. Hôm nay, nếu lo âu xuất hiện, hãy hỏi: điều này là sự thật, hay chỉ là cái bóng do nỗi sợ tạo ra? Hãy tin vào trực giác, nhưng chờ trời sáng rồi hãy kết luận.',
 'The Moon reminds you that in dim light, things can look more frightening than they are. If anxiety visits today, ask: is this real, or a shadow cast by fear? Trust your intuition, but wait for daylight before drawing conclusions.',
 'rws/the_moon.jpg'),
(20, 'the_sun', 'Mặt Trời', 'The Sun',
 'Niềm vui, thành công và nguồn năng lượng rực rỡ. Mọi thứ đang được soi sáng và sự ấm áp lan tỏa quanh bạn.',
 'Joy, success, and radiant vitality. Everything is illuminated, and warmth surrounds you.',
 'Niềm vui bị lu mờ tạm thời, sự lạc quan gượng ép, hoặc quên tận hưởng những điều tốt đẹp đang có.',
 'Joy temporarily dimmed, forced optimism, or forgetting to enjoy the good things already present.',
 'Mặt Trời mang đến một ngày tràn năng lượng tích cực. Hãy để bản thân tận hưởng những niềm vui giản dị — một tia nắng, một tiếng cười, một việc hoàn thành. Sự rạng rỡ của bạn hôm nay cũng sẽ sưởi ấm những người xung quanh.',
 'The Sun brings a day full of positive energy. Let yourself enjoy the simple pleasures — a ray of light, a shared laugh, a task completed. Your brightness today will warm the people around you too.',
 'rws/the_sun.jpg'),
(21, 'judgement', 'Sự Phán Xét', 'Judgement',
 'Sự thức tỉnh, đánh giá lại chặng đường đã qua và tiếng gọi hướng tới phiên bản tốt hơn của chính mình.',
 'Awakening, honest reflection on the road behind you, and a calling toward a better version of yourself.',
 'Sự tự phán xét khắc nghiệt, nghi ngờ bản thân, hoặc phớt lờ tiếng gọi thay đổi từ bên trong.',
 'Harsh self-judgment, self-doubt, or ignoring the inner call for change.',
 'Sự Phán Xét mời bạn nhìn lại chặng đường mình đã đi với lòng bao dung. Những bài học cũ không phải để dằn vặt, mà để bạn bước tiếp vững vàng hơn. Hôm nay, hãy tha thứ cho mình một điều, và lắng nghe tiếng gọi của con người mà bạn muốn trở thành.',
 'Judgement invites you to look back on your journey with compassion. Old lessons are not for self-blame — they are stepping stones. Today, forgive yourself for one thing, and listen to the call of the person you are becoming.',
 'rws/judgement.jpg'),
(22, 'the_world', 'Thế Giới', 'The World',
 'Sự viên mãn, hoàn thành một chu kỳ và cảm giác trọn vẹn. Bạn đã đi hết một vòng và xứng đáng ăn mừng thành quả.',
 'Completion, the closing of a cycle, and a sense of wholeness. You have come full circle and deserve to celebrate.',
 'Sự dang dở, thiếu một mảnh ghép cuối, hoặc chần chừ không chịu khép lại để bước sang chương mới.',
 'Incompletion, one missing piece, or hesitating to close a chapter and move on.',
 'Thế Giới nói về sự trọn vẹn. Hôm nay, hãy nhìn lại và ghi nhận những gì bạn đã hoàn thành — kể cả những điều nhỏ mà bạn thường bỏ qua. Mỗi chu kỳ khép lại đều mở ra một khởi đầu mới; hãy đón nó bằng lòng biết ơn.',
 'The World speaks of wholeness. Today, look back and acknowledge what you have completed — even the small things you usually overlook. Every closing cycle opens a new beginning; welcome it with gratitude.',
 'rws/the_world.jpg'),
(23, 'ace_of_wands', 'Át Gậy', 'Ace of Wands',
 'Nguồn cảm hứng mới, tia sáng sáng tạo và năng lượng khởi đầu. Một ý tưởng đầy tiềm năng đang chờ được thắp lửa.',
 'A new spark of inspiration, creative fire, and fresh energy. An idea full of potential is waiting to be ignited.',
 'Sự trì hoãn, thiếu động lực, hoặc một ý tưởng hay chưa tìm được hướng triển khai.',
 'Delays, lack of motivation, or a good idea that has not yet found its direction.',
 'Át Gậy mang đến ngọn lửa cảm hứng cho ngày hôm nay. Nếu có một ý tưởng cứ trở đi trở lại trong tâm trí bạn, đó có thể là dấu hiệu để bắt đầu. Đừng chờ mọi thứ hoàn hảo — chỉ cần một bước nhỏ đầu tiên là ngọn lửa sẽ bén.',
 'The Ace of Wands brings a flame of inspiration to your day. If an idea keeps returning to your mind, it may be a sign to begin. Don''t wait for perfect conditions — one small first step is enough to catch fire.',
 'rws/ace_of_wands.jpg'),
(24, 'two_of_wands', '2 Gậy', 'Two of Wands',
 'Tầm nhìn xa, lập kế hoạch và đứng trước những lựa chọn về tương lai. Thế giới đang rộng mở trong tay bạn.',
 'Foresight, planning, and standing before choices about your future. The world is opening up in your hands.',
 'Nỗi sợ bước ra khỏi vùng an toàn, kế hoạch thiếu chuẩn bị, hoặc chần chừ trước cơ hội lớn.',
 'Fear of leaving your comfort zone, poor planning, or hesitating before a big opportunity.',
 '2 Gậy mời bạn ngước nhìn xa hơn ngày hôm nay. Bạn đã có nền tảng — giờ là lúc phác thảo bước tiếp theo. Hãy dành vài phút hình dung nơi bạn muốn đến trong thời gian tới; một kế hoạch rõ ràng sẽ biến mong muốn thành lộ trình.',
 'The Two of Wands invites you to look beyond today. You already have a foundation — now it''s time to sketch the next move. Spend a few minutes picturing where you want to be; a clear plan turns a wish into a route.',
 'rws/two_of_wands.jpg'),
(25, 'three_of_wands', '3 Gậy', 'Three of Wands',
 'Sự mở rộng, tiến triển và những nỗ lực bắt đầu đơm hoa. Con thuyền bạn gửi đi đang dần trở về.',
 'Expansion, progress, and early efforts beginning to bear fruit. The ships you sent out are returning.',
 'Trở ngại ngoài dự tính, tiến độ chậm, hoặc tầm nhìn bị giới hạn bởi sự thiếu kiên nhẫn.',
 'Unexpected obstacles, slow progress, or vision narrowed by impatience.',
 '3 Gậy cho thấy những gì bạn đã gieo đang trên đường trở về với bạn. Hôm nay, hãy kiên nhẫn và tiếp tục hướng về phía trước — thành quả cần thời gian để cập bến. Trong lúc chờ đợi, hãy chuẩn bị sẵn sàng cho những cơ hội lớn hơn.',
 'The Three of Wands shows that what you planted is on its way back to you. Today, stay patient and keep facing forward — results need time to arrive. While you wait, prepare yourself for bigger opportunities.',
 'rws/three_of_wands.jpg'),
(26, 'four_of_wands', '4 Gậy', 'Four of Wands',
 'Niềm vui sum họp, sự ổn định và những cột mốc đáng ăn mừng. Tổ ấm và cộng đồng đang chào đón bạn.',
 'Celebration, stability, and milestones worth honoring. Home and community are welcoming you.',
 'Sự thiếu gắn kết, mái ấm chưa trọn vẹn, hoặc một giai đoạn chuyển tiếp còn dang dở.',
 'A lack of belonging, tension at home, or a transition still incomplete.',
 '4 Gậy mang không khí của sự sum vầy và ăn mừng. Hôm nay, hãy dành thời gian cho những người khiến bạn cảm thấy được là chính mình. Một bữa cơm chung, một cuộc gọi hỏi thăm — những khoảnh khắc ấy chính là nền móng của hạnh phúc.',
 'The Four of Wands carries the warmth of gathering and celebration. Today, make time for the people who let you be yourself. A shared meal, a caring call — these moments are the true foundation of happiness.',
 'rws/four_of_wands.jpg'),
(27, 'five_of_wands', '5 Gậy', 'Five of Wands',
 'Sự cạnh tranh, va chạm ý kiến và những xung đột nhỏ. Mỗi cuộc tranh luận đều có thể trở thành cơ hội học hỏi.',
 'Competition, clashing opinions, and minor conflicts. Every disagreement can become a chance to learn.',
 'Né tránh xung đột, căng thẳng được giải tỏa, hoặc tìm được tiếng nói chung sau va chạm.',
 'Avoiding conflict, tension easing, or finding common ground after friction.',
 '5 Gậy báo hiệu một ngày có thể nhiều va chạm ý kiến. Thay vì cố thắng mọi cuộc tranh luận, hãy thử lắng nghe điều ẩn sau quan điểm của người khác. Sự khác biệt hôm nay có thể là chất liệu cho giải pháp tốt hơn ngày mai.',
 'The Five of Wands hints at a day of clashing views. Instead of trying to win every argument, listen for what lies behind the other person''s position. Today''s differences may become the raw material for tomorrow''s better solution.',
 'rws/five_of_wands.jpg'),
(28, 'six_of_wands', '6 Gậy', 'Six of Wands',
 'Chiến thắng, sự công nhận và niềm tự hào xứng đáng. Nỗ lực của bạn đang được nhìn thấy và tôn vinh.',
 'Victory, recognition, and well-earned pride. Your efforts are being seen and celebrated.',
 'Thành công bị trì hoãn, thiếu sự ghi nhận, hoặc cái tôi che mờ giá trị thật của thành quả.',
 'Delayed success, lack of recognition, or ego overshadowing the true worth of an achievement.',
 '6 Gậy mang đến năng lượng của sự công nhận. Hôm nay, đừng ngại đón nhận lời khen — bạn đã nỗ lực để xứng đáng với nó. Và nếu có thể, hãy trao sự ghi nhận ấy cho một người khác cũng đang âm thầm cố gắng.',
 'The Six of Wands brings the energy of recognition. Today, don''t shy away from praise — you have worked hard to earn it. And if you can, pass that recognition on to someone else who is quietly doing their best.',
 'rws/six_of_wands.jpg'),
(29, 'seven_of_wands', '7 Gậy', 'Seven of Wands',
 'Sự kiên định, bảo vệ lập trường và lòng dũng cảm trước thử thách. Bạn đang ở thế cao hơn bạn nghĩ.',
 'Perseverance, standing your ground, and courage under pressure. You hold higher ground than you realize.',
 'Cảm giác quá tải, muốn bỏ cuộc, hoặc mệt mỏi vì phải phòng thủ quá lâu.',
 'Feeling overwhelmed, wanting to give up, or worn out from being on the defensive too long.',
 '7 Gậy nhắc bạn rằng việc giữ vững lập trường đôi khi cần nhiều can đảm hơn cả tiến lên. Nếu hôm nay có áp lực khiến bạn dao động, hãy nhớ lý do bạn bắt đầu. Bạn không cần thắng tất cả — chỉ cần không từ bỏ điều thực sự quan trọng.',
 'The Seven of Wands reminds you that holding your ground can take more courage than advancing. If pressure shakes you today, remember why you started. You don''t have to win everything — just don''t give up what truly matters.',
 'rws/seven_of_wands.jpg'),
(30, 'eight_of_wands', '8 Gậy', 'Eight of Wands',
 'Tốc độ, tin tức tốt lành và mọi thứ chuyển động nhanh chóng. Hãy sẵn sàng vì các sự kiện đang dồn dập đến.',
 'Swiftness, good news, and rapid movement. Be ready — events are arriving in quick succession.',
 'Sự chậm trễ gây nản lòng, thông tin nhiễu loạn, hoặc hành động vội vàng thiếu suy tính.',
 'Frustrating delays, mixed signals, or hasty action without enough thought.',
 '8 Gậy báo hiệu một ngày mọi thứ có thể diễn ra rất nhanh — tin nhắn, cơ hội, thay đổi. Hãy giữ sự linh hoạt và ưu tiên điều quan trọng nhất. Khi dòng chảy đến, việc của bạn là thuận theo nó thay vì gồng mình cản lại.',
 'The Eight of Wands signals a fast-moving day — messages, opportunities, sudden shifts. Stay flexible and keep your top priority clear. When the current arrives, your job is to ride it, not to fight it.',
 'rws/eight_of_wands.jpg'),
(31, 'nine_of_wands', '9 Gậy', 'Nine of Wands',
 'Sự bền bỉ, kiên cường sau nhiều thử thách và chặng cuối trước vạch đích. Vết thương cũ chính là minh chứng bạn đã đi xa đến đâu.',
 'Resilience, endurance after many trials, and the last stretch before the finish line. Your old scars prove how far you have come.',
 'Sự kiệt sức, phòng thủ quá mức, hoặc nghi ngờ mọi người vì những tổn thương chưa lành.',
 'Exhaustion, excessive defensiveness, or distrusting everyone because of unhealed wounds.',
 '9 Gậy nhắc bạn rằng mình đã đi được rất xa, dù đôi chân có mỏi. Hôm nay, nếu cảm thấy muốn buông, hãy nghỉ một nhịp thay vì bỏ cuộc. Chặng đường còn lại ngắn hơn chặng đường bạn đã vượt qua.',
 'The Nine of Wands reminds you how far you have already come, even if you are weary. If you feel like quitting today, rest for a beat instead of walking away. The road left ahead is shorter than the one behind you.',
 'rws/nine_of_wands.jpg'),
(32, 'ten_of_wands', '10 Gậy', 'Ten of Wands',
 'Gánh nặng trách nhiệm và sự nỗ lực gồng gánh quá nhiều. Thành công đang gần, nhưng bạn không cần vác tất cả một mình.',
 'The weight of responsibility and carrying too much at once. Success is near, but you don''t have to carry it all alone.',
 'Buông bớt gánh nặng, học cách san sẻ, hoặc kiệt sức vì ôm đồm kéo dài.',
 'Releasing burdens, learning to delegate, or burnout from carrying too much for too long.',
 '10 Gậy hỏi bạn: trong những gánh nặng đang mang, cái nào thực sự là của bạn? Hôm nay, hãy thử đặt xuống một việc — nhờ giúp đỡ, hoãn lại, hoặc đơn giản là từ chối. Sức bền của bạn quý giá; hãy dành nó cho điều xứng đáng.',
 'The Ten of Wands asks: of all the burdens you carry, which are truly yours? Today, try putting one down — ask for help, postpone it, or simply say no. Your endurance is precious; spend it on what deserves it.',
 'rws/ten_of_wands.jpg'),
(33, 'page_of_wands', 'Tiểu Đồng Gậy', 'Page of Wands',
 'Tinh thần khám phá, nhiệt huyết tươi mới và tin vui đang đến. Thế giới đầy điều thú vị đang chờ bạn thử sức.',
 'A spirit of exploration, fresh enthusiasm, and exciting news on the way. The world is full of things worth trying.',
 'Sự thiếu định hướng, hứng khởi chóng tàn, hoặc những ý tưởng chưa đủ chín để hành động.',
 'Lack of direction, short-lived excitement, or ideas not yet mature enough for action.',
 'Tiểu Đồng Gậy mang đến sự tò mò trẻ trung cho ngày của bạn. Hãy thử một điều nhỏ mà bạn chưa từng làm — một con đường mới, một món ăn lạ, một câu hỏi táo bạo. Sự hào hứng chân thành chính là la bàn tốt nhất hôm nay.',
 'The Page of Wands brings youthful curiosity to your day. Try one small thing you''ve never done — a new route, an unfamiliar dish, a bold question. Genuine excitement is your best compass today.',
 'rws/page_of_wands.jpg'),
(34, 'knight_of_wands', 'Hiệp Sĩ Gậy', 'Knight of Wands',
 'Năng lượng bùng nổ, đam mê và tinh thần hành động không ngần ngại. Bạn đang có đà để lao về phía mục tiêu.',
 'Bursting energy, passion, and fearless action. You have momentum to charge toward your goal.',
 'Sự bốc đồng, nóng vội, hoặc năng lượng phân tán khiến mọi việc dở dang.',
 'Impulsiveness, haste, or scattered energy leaving things unfinished.',
 'Hiệp Sĩ Gậy thúc giục bạn hành động với tất cả nhiệt huyết. Hôm nay là ngày tốt để bắt tay vào việc bạn đã ấp ủ — nhưng hãy nhớ giữ một tay trên dây cương. Đam mê cộng với một chút kiểm soát sẽ đưa bạn đi xa nhất.',
 'The Knight of Wands urges you to act with full passion. Today is a good day to start what you''ve been dreaming about — just keep one hand on the reins. Passion plus a little control will carry you furthest.',
 'rws/knight_of_wands.jpg'),
(35, 'queen_of_wands', 'Hoàng Hậu Gậy', 'Queen of Wands',
 'Sự tự tin rạng rỡ, ấm áp và quyết đoán. Bạn thu hút người khác bằng chính nguồn năng lượng chân thật của mình.',
 'Radiant confidence, warmth, and determination. You draw others in with your authentic energy.',
 'Sự bất an, ghen tị, hoặc ngọn lửa nội tâm đang bị nghi ngờ bản thân che khuất.',
 'Insecurity, jealousy, or an inner fire dimmed by self-doubt.',
 'Hoàng Hậu Gậy mời bạn tỏa sáng theo cách riêng của mình. Hôm nay, hãy đứng thẳng, nói điều bạn nghĩ với sự ấm áp, và tin vào sức hút tự nhiên của bản thân. Khi bạn sống trọn vẹn là chính mình, đúng người sẽ bị thu hút về phía bạn.',
 'The Queen of Wands invites you to shine in your own way. Today, stand tall, speak your mind with warmth, and trust your natural charisma. When you are fully yourself, the right people are drawn to you.',
 'rws/queen_of_wands.jpg'),
(36, 'king_of_wands', 'Vua Gậy', 'King of Wands',
 'Tầm nhìn lãnh đạo, sự táo bạo và khả năng truyền cảm hứng. Bạn có thể biến một ý tưởng lớn thành hiện thực bền vững.',
 'Visionary leadership, boldness, and the power to inspire. You can turn a big idea into lasting reality.',
 'Sự độc đoán, kỳ vọng quá cao, hoặc nóng nảy khiến người khác e ngại thay vì được truyền cảm hứng.',
 'Domineering behavior, unrealistic expectations, or a temper that intimidates rather than inspires.',
 'Vua Gậy mời bạn nghĩ lớn và dẫn dắt bằng gương mẫu. Hôm nay, thay vì chờ ai đó chỉ đường, hãy tự hỏi: nếu mình là người quyết định, mình sẽ làm gì? Câu trả lời ấy có thể chính là hướng đi bạn đang tìm kiếm.',
 'The King of Wands invites you to think big and lead by example. Today, instead of waiting for direction, ask yourself: if I were the one deciding, what would I do? That answer may be the direction you''ve been seeking.',
 'rws/king_of_wands.jpg'),
(37, 'ace_of_cups', 'Át Cốc', 'Ace of Cups',
 'Khởi đầu mới về cảm xúc, tình yêu và lòng trắc ẩn tuôn trào. Trái tim bạn đang được rót đầy.',
 'A new emotional beginning, love, and overflowing compassion. Your heart is being filled.',
 'Cảm xúc bị dồn nén, trái tim khép lại, hoặc cho đi quá nhiều đến mức cạn kiệt.',
 'Repressed emotions, a closed heart, or giving so much that you run dry.',
 'Át Cốc mang đến dòng chảy cảm xúc tươi mới. Hôm nay, hãy cho phép trái tim mình rộng mở — với một người, một ý tưởng, hay chính bản thân bạn. Tình cảm chân thành bạn trao đi sẽ quay về đầy đặn hơn.',
 'The Ace of Cups brings a fresh flow of feeling. Today, let your heart open — to a person, an idea, or yourself. The genuine affection you give away returns even fuller.',
 'rws/ace_of_cups.jpg'),
(38, 'two_of_cups', '2 Cốc', 'Two of Cups',
 'Sự kết nối đôi bên, tình cảm được đáp lại và mối quan hệ hòa hợp. Hai trái tim đang tìm thấy tiếng nói chung.',
 'Mutual connection, reciprocated feelings, and a harmonious bond. Two hearts are finding common ground.',
 'Sự mất cân bằng trong mối quan hệ, hiểu lầm, hoặc khoảng cách đang lớn dần giữa hai người.',
 'Imbalance in a relationship, misunderstanding, or a growing distance between two people.',
 '2 Cốc nói về sự kết nối chân thành giữa người với người. Hôm nay, hãy dành sự chú tâm trọn vẹn cho một người quan trọng với bạn — lắng nghe mà không phán xét. Những mối quan hệ đẹp được nuôi bằng chính những khoảnh khắc như thế.',
 'The Two of Cups speaks of genuine connection. Today, give your full presence to someone who matters — listen without judgment. Beautiful relationships are nourished by exactly these moments.',
 'rws/two_of_cups.jpg'),
(39, 'three_of_cups', '3 Cốc', 'Three of Cups',
 'Tình bạn, niềm vui chung và sự ăn mừng cùng những người thân thiết. Hạnh phúc nhân lên khi được sẻ chia.',
 'Friendship, shared joy, and celebration with kindred spirits. Happiness multiplies when it is shared.',
 'Sự lạc lõng giữa đám đông, chuyện phiếm gây tổn thương, hoặc vui chơi quá đà làm lệch trọng tâm.',
 'Feeling alone in a crowd, hurtful gossip, or overindulgence pulling you off balance.',
 '3 Cốc mang năng lượng của tình bạn và niềm vui sẻ chia. Hôm nay, hãy chủ động kết nối — nhắn tin cho người bạn lâu chưa gặp, hoặc đơn giản là cùng ai đó cười thật thoải mái. Bạn không cần lý do đặc biệt để ăn mừng cuộc sống.',
 'The Three of Cups carries the energy of friendship and shared joy. Today, reach out — message a friend you haven''t seen in a while, or simply share a good laugh with someone. You don''t need a special reason to celebrate life.',
 'rws/three_of_cups.jpg'),
(40, 'four_of_cups', '4 Cốc', 'Four of Cups',
 'Sự thờ ơ, chán nản và mải nhìn vào những gì đã mất. Một món quà đang được trao mà bạn chưa nhận ra.',
 'Apathy, discontent, and dwelling on what is missing. A gift is being offered that you have not yet noticed.',
 'Sự tỉnh thức khỏi trạng thái trì trệ, động lực quay trở lại, hoặc mở lòng đón nhận cơ hội mới.',
 'Waking from stagnation, motivation returning, or opening up to a new opportunity.',
 '4 Cốc nhắc bạn ngẩng đầu lên khỏi những suy tư. Có thể một cơ hội hay một sự quan tâm đang ở ngay trước mắt mà bạn chưa để ý. Hôm nay, hãy thử đếm ba điều bạn đang có thay vì ba điều còn thiếu — góc nhìn sẽ thay đổi mọi thứ.',
 'The Four of Cups reminds you to lift your gaze from your brooding. An opportunity or a kind gesture may be right in front of you, unnoticed. Today, try counting three things you have instead of three things you lack — perspective changes everything.',
 'rws/four_of_cups.jpg'),
(41, 'five_of_cups', '5 Cốc', 'Five of Cups',
 'Nỗi buồn, sự tiếc nuối và tập trung vào mất mát. Nhưng phía sau bạn, vẫn còn những chiếc cốc chưa đổ.',
 'Sorrow, regret, and focusing on loss. Yet behind you, some cups still stand full.',
 'Sự chấp nhận, buông bỏ tiếc nuối, và bước đầu của quá trình chữa lành sau mất mát.',
 'Acceptance, releasing regret, and the first steps of healing after loss.',
 '5 Cốc thừa nhận rằng nỗi buồn của bạn là có thật và xứng đáng được cảm nhận. Nhưng lá bài cũng nhẹ nhàng nhắc: không phải tất cả đều đã mất. Hôm nay, khi đã khóc đủ cho những chiếc cốc đổ, hãy quay lại nhìn những chiếc còn nguyên.',
 'The Five of Cups acknowledges that your sadness is real and deserves to be felt. But the card also gently reminds you: not everything is lost. Today, once you have grieved the spilled cups, turn around and see the ones still standing.',
 'rws/five_of_cups.jpg'),
(42, 'six_of_cups', '6 Cốc', 'Six of Cups',
 'Ký ức êm đềm, sự hoài niệm và lòng tốt hồn nhiên. Quá khứ đang gửi đến bạn một món quà dịu dàng.',
 'Sweet memories, nostalgia, and innocent kindness. The past is sending you a gentle gift.',
 'Sống mãi trong quá khứ, níu kéo những gì đã qua, hoặc cần buông ký ức để bước tiếp.',
 'Living in the past, clinging to what is gone, or needing to release old memories to move on.',
 '6 Cốc mang hương vị của những ký ức đẹp. Hôm nay, một điều gợi nhớ tuổi thơ hay một người bạn cũ có thể khiến lòng bạn ấm lại. Hãy trân trọng món quà ấy — và mang sự hồn nhiên đó vào hiện tại thay vì chỉ ngoái nhìn.',
 'The Six of Cups carries the flavor of cherished memories. Today, something nostalgic or an old friend may warm your heart. Treasure that gift — and bring that innocence into the present rather than only looking back.',
 'rws/six_of_cups.jpg'),
(43, 'seven_of_cups', '7 Cốc', 'Seven of Cups',
 'Nhiều lựa chọn, mơ mộng và những ảo ảnh hấp dẫn. Không phải chiếc cốc nào lấp lánh cũng chứa điều bạn thật sự cần.',
 'Many choices, daydreams, and tempting illusions. Not every glittering cup holds what you truly need.',
 'Sự tỉnh táo trở lại, quyết định được đưa ra, hoặc thoát khỏi những ảo tưởng để nhìn rõ thực tế.',
 'Clarity returning, a decision finally made, or breaking free from illusions to see reality.',
 '7 Cốc nói về những lựa chọn đang bày ra trước mắt bạn. Hôm nay, thay vì để mọi khả năng làm mình choáng ngợp, hãy hỏi: điều nào phù hợp với giá trị thật của mình? Mơ ước là khởi đầu tốt — nhưng chỉ lựa chọn mới đưa bạn đi tiếp.',
 'The Seven of Cups speaks of the options spread before you. Today, instead of being overwhelmed by possibilities, ask: which one aligns with my true values? Dreaming is a fine start — but only choosing moves you forward.',
 'rws/seven_of_cups.jpg'),
(44, 'eight_of_cups', '8 Cốc', 'Eight of Cups',
 'Sự rời đi để tìm kiếm ý nghĩa sâu sắc hơn. Bạn đủ can đảm để bỏ lại điều không còn nuôi dưỡng tâm hồn mình.',
 'Walking away in search of deeper meaning. You are brave enough to leave behind what no longer nourishes your soul.',
 'Nỗi sợ thay đổi, chần chừ giữa đi và ở, hoặc quay lại với điều mình từng rời bỏ.',
 'Fear of change, wavering between staying and leaving, or returning to what you once walked away from.',
 '8 Cốc hỏi bạn một câu thẳng thắn: điều gì trong cuộc sống không còn thực sự nuôi dưỡng bạn? Rời đi không phải là thất bại — đó là sự trung thực với chính mình. Hôm nay, hãy lắng nghe tiếng gọi của điều có ý nghĩa hơn.',
 'The Eight of Cups asks you an honest question: what in your life no longer truly nourishes you? Walking away is not failure — it is honesty with yourself. Today, listen for the call of something more meaningful.',
 'rws/eight_of_cups.jpg'),
(45, 'nine_of_cups', '9 Cốc', 'Nine of Cups',
 'Sự mãn nguyện, ước nguyện thành hiện thực và niềm vui được tận hưởng thành quả. Đây là lá bài của điều ước.',
 'Contentment, wishes coming true, and the joy of savoring your rewards. This is the wish card.',
 'Sự thỏa mãn hời hợt, tham lam, hoặc nhận ra vật chất không lấp đầy được khoảng trống bên trong.',
 'Shallow satisfaction, greed, or realizing that material comfort cannot fill an inner emptiness.',
 '9 Cốc là lá bài của sự mãn nguyện. Hôm nay, hãy cho phép mình tận hưởng những gì đang có mà không cảm thấy áy náy. Niềm vui không cần phải chờ đến khi mọi thứ hoàn hảo — nó nằm trong chính khoảnh khắc bạn biết ơn hiện tại.',
 'The Nine of Cups is the card of contentment. Today, allow yourself to enjoy what you have without guilt. Joy doesn''t have to wait until everything is perfect — it lives in the moment you feel grateful for now.',
 'rws/nine_of_cups.jpg'),
(46, 'ten_of_cups', '10 Cốc', 'Ten of Cups',
 'Hạnh phúc viên mãn, tình thân ấm áp và sự hòa hợp trong gia đình. Trái tim bạn đã tìm thấy bến đỗ bình yên.',
 'Lasting happiness, loving bonds, and family harmony. Your heart has found its safe harbor.',
 'Sự rạn nứt trong gia đình, kỳ vọng về hạnh phúc hoàn hảo, hoặc mái ấm cần được vun đắp lại.',
 'Family discord, chasing a picture-perfect ideal, or a home that needs mending.',
 '10 Cốc vẽ nên bức tranh của hạnh phúc trọn vẹn. Hôm nay, hãy nhìn những người thân yêu quanh bạn bằng ánh mắt biết ơn — hạnh phúc thường giản dị hơn ta tưởng. Một khoảnh khắc quây quần cũng đủ làm đầy trái tim.',
 'The Ten of Cups paints a picture of complete happiness. Today, look at your loved ones with grateful eyes — happiness is often simpler than we think. One moment of togetherness is enough to fill the heart.',
 'rws/ten_of_cups.jpg'),
(47, 'page_of_cups', 'Tiểu Đồng Cốc', 'Page of Cups',
 'Thông điệp từ trái tim, trực giác tươi mới và sự sáng tạo hồn nhiên. Hãy đón nhận những bất ngờ dễ thương của cảm xúc.',
 'A message from the heart, fresh intuition, and playful creativity. Welcome the sweet surprises of your feelings.',
 'Sự nhạy cảm thái quá, cảm xúc non nớt, hoặc trốn vào mơ mộng để né tránh thực tại.',
 'Oversensitivity, emotional immaturity, or escaping into daydreams to avoid reality.',
 'Tiểu Đồng Cốc mang đến sự tươi mới cho tâm hồn bạn. Hôm nay, hãy để trí tưởng tượng được chơi đùa — viết vài dòng, vẽ nguệch ngoạc, hay đơn giản là mơ mộng một chút. Những rung động nhỏ của trái tim đang mang theo thông điệp đáng nghe.',
 'The Page of Cups brings freshness to your spirit. Today, let your imagination play — write a few lines, doodle, or simply daydream a little. The small stirrings of your heart carry messages worth hearing.',
 'rws/page_of_cups.jpg'),
(48, 'knight_of_cups', 'Hiệp Sĩ Cốc', 'Knight of Cups',
 'Sự lãng mạn, lời mời gọi từ trái tim và hành động theo cảm xúc chân thành. Một cử chỉ đẹp đang trên đường đến với bạn.',
 'Romance, an invitation from the heart, and acting on genuine feeling. A beautiful gesture is on its way to you.',
 'Sự thất thường, hứa hẹn viển vông, hoặc để cảm xúc dẫn dắt mà quên mất thực tế.',
 'Moodiness, empty promises, or letting emotions lead while losing sight of reality.',
 'Hiệp Sĩ Cốc khuyến khích bạn hành động theo tiếng gọi của trái tim. Hôm nay là ngày đẹp để bày tỏ — một lời cảm ơn, một tin nhắn quan tâm, một cử chỉ lãng mạn. Sự chân thành của bạn có sức lay động hơn bạn nghĩ.',
 'The Knight of Cups encourages you to act on your heart''s call. Today is a lovely day to express yourself — a thank-you, a caring message, a romantic gesture. Your sincerity moves people more than you know.',
 'rws/knight_of_cups.jpg'),
(49, 'queen_of_cups', 'Hoàng Hậu Cốc', 'Queen of Cups',
 'Lòng trắc ẩn sâu sắc, trực giác tinh tế và sự vững vàng trong cảm xúc. Bạn là điểm tựa dịu dàng cho chính mình và người khác.',
 'Deep compassion, refined intuition, and emotional steadiness. You are a gentle anchor for yourself and others.',
 'Sự quá tải cảm xúc, phụ thuộc tình cảm, hoặc chăm lo người khác đến quên cả chính mình.',
 'Emotional overwhelm, dependency, or caring for everyone else while forgetting yourself.',
 'Hoàng Hậu Cốc nhắc bạn về sức mạnh của sự thấu cảm. Hôm nay, hãy lắng nghe cảm xúc của mình và của người khác bằng sự dịu dàng không phán xét. Nhưng cũng đừng quên: chiếc cốc của bạn cũng cần được rót đầy trước khi san sẻ.',
 'The Queen of Cups reminds you of the power of empathy. Today, listen to your feelings and others'' with gentle, non-judgmental attention. But remember: your own cup needs filling before you can pour for others.',
 'rws/queen_of_cups.jpg'),
(50, 'king_of_cups', 'Vua Cốc', 'King of Cups',
 'Sự điềm tĩnh giữa sóng gió, cân bằng giữa lý trí và cảm xúc. Bạn có thể cảm nhận sâu sắc mà vẫn giữ được sự sáng suốt.',
 'Calm amid the waves, balancing head and heart. You can feel deeply while staying clear-minded.',
 'Cảm xúc bị kìm nén, sự lạnh lùng, hoặc dùng cảm xúc của người khác để thao túng.',
 'Suppressed emotions, coldness, or using others'' feelings to manipulate.',
 'Vua Cốc mời bạn giữ sự điềm tĩnh giữa những cảm xúc dâng cao. Hôm nay, nếu có điều gì khiến lòng bạn xao động, hãy cho mình một nhịp thở trước khi phản ứng. Cảm nhận trọn vẹn nhưng hành xử sáng suốt — đó là sức mạnh thật sự.',
 'The King of Cups invites you to stay steady amid rising emotions. Today, if something stirs you, give yourself one breath before reacting. Feeling fully while acting wisely — that is real strength.',
 'rws/king_of_cups.jpg'),
(51, 'ace_of_swords', 'Át Kiếm', 'Ace of Swords',
 'Sự minh mẫn đột phá, chân lý sắc bén và một ý tưởng mới đầy sức mạnh. Màn sương đang tan để lộ ra sự thật.',
 'A breakthrough of clarity, sharp truth, and a powerful new idea. The fog is lifting to reveal what is real.',
 'Sự rối trí, thông tin sai lệch, hoặc lời nói sắc bén gây tổn thương thay vì soi sáng.',
 'Confusion, misinformation, or sharp words that wound instead of illuminate.',
 'Át Kiếm mang đến sự sáng rõ cho tâm trí bạn. Hôm nay, một vấn đề rối rắm có thể bỗng trở nên đơn giản khi bạn gọi đúng tên nó. Hãy dùng sự minh mẫn ấy một cách tử tế — sự thật sắc bén nhất khi đi cùng lòng trắc ẩn.',
 'The Ace of Swords brings clarity to your mind. Today, a tangled problem may suddenly become simple once you name it truthfully. Use that clarity kindly — truth cuts cleanest when paired with compassion.',
 'rws/ace_of_swords.jpg'),
(52, 'two_of_swords', '2 Kiếm', 'Two of Swords',
 'Thế lưỡng nan, quyết định bị trì hoãn và sự bịt mắt trước lựa chọn khó. Việc né tránh cũng là một cái giá phải trả.',
 'A stalemate, a postponed decision, and a blindfold before a hard choice. Avoiding it has its own cost.',
 'Bế tắc được tháo gỡ, thông tin mới xuất hiện, hoặc buộc phải đối diện với lựa chọn đã né tránh.',
 'The deadlock breaking, new information surfacing, or finally facing the choice you avoided.',
 '2 Kiếm hiểu rằng có những quyết định thật khó đưa ra. Hôm nay, thay vì ép mình chọn ngay, hãy tháo "tấm bịt mắt": viết ra điều bạn thực sự sợ ở mỗi lựa chọn. Khi nỗi sợ được gọi tên, con đường thường tự hiện ra.',
 'The Two of Swords understands that some decisions are genuinely hard. Today, instead of forcing a choice, remove the blindfold: write down what you truly fear about each option. Once fear is named, the path often reveals itself.',
 'rws/two_of_swords.jpg'),
(53, 'three_of_swords', '3 Kiếm', 'Three of Swords',
 'Nỗi đau lòng, sự thật gây tổn thương và trái tim cần thời gian. Cơn mưa nào rồi cũng sẽ tạnh.',
 'Heartbreak, a painful truth, and a heart that needs time. Every storm eventually passes.',
 'Vết thương đang lành lại, sự tha thứ, hoặc buông bỏ nỗi đau đã mang quá lâu.',
 'A wound beginning to heal, forgiveness, or releasing pain carried for too long.',
 '3 Kiếm không né tránh sự thật rằng có những ngày trái tim ta đau. Nếu hôm nay là một ngày như thế, đừng vội ép mình ổn — hãy cho nỗi buồn không gian để được cảm nhận. Trái tim con người có khả năng lành lại đáng kinh ngạc, và bạn cũng vậy.',
 'The Three of Swords doesn''t deny that some days the heart simply hurts. If today is one of those days, don''t rush to be okay — give your sadness room to breathe. The human heart has a remarkable ability to heal, and so do you.',
 'rws/three_of_swords.jpg'),
(54, 'four_of_swords', '4 Kiếm', 'Four of Swords',
 'Sự nghỉ ngơi, phục hồi và khoảng lặng cần thiết cho tâm trí. Tạm dừng không phải là bỏ cuộc.',
 'Rest, recovery, and a needed pause for the mind. Stopping to rest is not giving up.',
 'Sự bồn chồn không cho phép mình nghỉ, kiệt sức tích tụ, hoặc đã đến lúc phải quay lại hành động.',
 'Restlessness that refuses rest, mounting burnout, or the moment to return to action.',
 '4 Kiếm là lời nhắc dịu dàng: bạn được phép nghỉ ngơi. Hôm nay, hãy tìm một khoảng lặng thật sự — chợp mắt, tắt thông báo, hay chỉ ngồi yên vài phút. Tâm trí được nghỉ ngơi sẽ trả lại cho bạn sự sáng suốt gấp nhiều lần.',
 'The Four of Swords is a gentle reminder: you are allowed to rest. Today, find a true pause — a nap, silenced notifications, or a few minutes of simply sitting still. A rested mind repays you with clarity many times over.',
 'rws/four_of_swords.jpg'),
(55, 'five_of_swords', '5 Kiếm', 'Five of Swords',
 'Xung đột căng thẳng, chiến thắng phải trả giá đắt. Có những cuộc tranh cãi mà thắng cũng là thua.',
 'Tense conflict and victory at too high a price. Some arguments are lost even when won.',
 'Sự hòa giải, buông bỏ hiềm khích, hoặc nhận ra cái giá thật sự của việc hơn thua.',
 'Reconciliation, letting go of grudges, or realizing the true cost of needing to win.',
 '5 Kiếm đặt ra một câu hỏi đáng suy ngẫm: chiến thắng này có xứng đáng với cái giá của nó không? Hôm nay, nếu đứng trước một cuộc tranh luận, hãy cân nhắc giữ hòa khí thay vì giữ phần thắng. Đôi khi lùi một bước lại là bước đi khôn ngoan nhất.',
 'The Five of Swords asks a question worth pondering: is this victory worth its price? Today, if an argument arises, consider protecting the relationship over winning the point. Sometimes stepping back is the wisest move forward.',
 'rws/five_of_swords.jpg'),
(56, 'six_of_swords', '6 Kiếm', 'Six of Swords',
 'Sự chuyển tiếp rời xa sóng gió, hướng về vùng nước êm hơn. Bạn đang trên hành trình chữa lành, dù chậm rãi.',
 'A passage away from rough waters toward calmer shores. You are on a healing journey, however slow.',
 'Sự níu kéo quá khứ, hành trình chuyển tiếp bị trì hoãn, hoặc mang theo gánh nặng cũ sang chặng mới.',
 'Clinging to the past, a delayed transition, or carrying old baggage into a new chapter.',
 '6 Kiếm nhắc rằng bạn đang di chuyển về phía bình yên, dù con thuyền đi chậm. Hôm nay, đừng đo hành trình bằng tốc độ — hãy đo bằng hướng đi. Miễn là bạn đang rời xa điều làm mình tổn thương, bạn đang đi đúng đường.',
 'The Six of Swords reminds you that you are moving toward calmer waters, even if the boat feels slow. Today, measure your journey not by speed but by direction. As long as you are moving away from what hurt you, you are on the right path.',
 'rws/six_of_swords.jpg'),
(57, 'seven_of_swords', '7 Kiếm', 'Seven of Swords',
 'Sự khôn khéo, chiến lược, nhưng cũng có thể là lừa dối hoặc hành động lén lút. Hãy tỉnh táo với điều không được nói ra.',
 'Cunning and strategy, but possibly deception or acting in secret. Stay alert to what is left unsaid.',
 'Sự thú nhận, bí mật được phơi bày, hoặc quyết định sống ngay thẳng sau thời gian né tránh.',
 'A confession, a secret coming to light, or choosing honesty after a time of avoidance.',
 '7 Kiếm mời bạn nhìn mọi việc hôm nay bằng con mắt tỉnh táo. Không phải ai cũng nói hết những gì họ nghĩ — và đôi khi chính ta cũng vậy. Hãy tự hỏi: mình có đang trung thực với bản thân và người khác không? Sự ngay thẳng luôn là chiến lược bền vững nhất.',
 'The Seven of Swords invites you to keep clear eyes today. Not everyone says all they think — and sometimes neither do we. Ask yourself: am I being honest with myself and others? Integrity remains the most durable strategy.',
 'rws/seven_of_swords.jpg'),
(58, 'eight_of_swords', '8 Kiếm', 'Eight of Swords',
 'Cảm giác bị trói buộc bởi hoàn cảnh, nhưng sợi dây thật ra do suy nghĩ tự tạo. Bạn tự do hơn bạn tưởng.',
 'Feeling trapped by circumstance, though the ropes are woven by your own thoughts. You are freer than you believe.',
 'Sự giải thoát khỏi giới hạn tự đặt, góc nhìn mới, hoặc bước đầu tiên ra khỏi tình thế tưởng như bế tắc.',
 'Release from self-imposed limits, a new perspective, or the first step out of a seemingly hopeless bind.',
 '8 Kiếm nhẹ nhàng chỉ ra rằng nhiều giới hạn ta cảm thấy thực ra nằm trong suy nghĩ. Hôm nay, hãy thử thách một niềm tin "mình không thể" bằng câu hỏi: điều đó có thật sự đúng không? Chỉ cần nhìn thấy sợi dây là lỏng, bạn đã bắt đầu tự do.',
 'The Eight of Swords gently points out that many of the limits we feel live in our thinking. Today, challenge one "I can''t" belief with the question: is that actually true? The moment you see the ropes are loose, freedom has already begun.',
 'rws/eight_of_swords.jpg'),
(59, 'nine_of_swords', '9 Kiếm', 'Nine of Swords',
 'Lo âu, mất ngủ và những suy nghĩ dằn vặt trong đêm. Nỗi sợ trong tâm trí thường lớn hơn thực tế ngoài kia.',
 'Anxiety, sleepless nights, and tormenting thoughts. The fears in your mind are often larger than reality outside.',
 'Nỗi lo dần được giải tỏa, ánh sáng cuối đường hầm, hoặc học cách đối diện thay vì gặm nhấm sợ hãi.',
 'Worry beginning to ease, light at the end of the tunnel, or learning to face fears instead of feeding them.',
 '9 Kiếm thấu hiểu những đêm trằn trọc của bạn. Nhưng hãy nhớ: lo âu là kẻ phóng đại tài ba — nó vẽ mọi thứ tối hơn thực tế. Hôm nay, hãy viết nỗi lo lớn nhất ra giấy và nhìn nó dưới ánh sáng ban ngày; nó thường nhỏ hơn bóng của chính nó.',
 'The Nine of Swords understands your restless nights. But remember: anxiety is a masterful exaggerator — it paints everything darker than reality. Today, write your biggest worry down and look at it in daylight; it is usually smaller than its own shadow.',
 'rws/nine_of_swords.jpg'),
(60, 'ten_of_swords', '10 Kiếm', 'Ten of Swords',
 'Sự kết thúc đau đớn, chạm đáy, nhưng cũng là điểm khởi đầu của bình minh. Điều tồi tệ nhất đã ở phía sau bạn.',
 'A painful ending and rock bottom — yet also the point where dawn begins. The worst is behind you.',
 'Sự hồi phục sau biến cố, đứng dậy từ thất bại, hoặc thoát khỏi tâm thế nạn nhân để làm lại.',
 'Recovery after a crisis, rising from failure, or leaving the victim role behind to begin again.',
 '10 Kiếm mang một thông điệp nghịch lý mà an ủi: khi đã chạm đáy, con đường duy nhất là đi lên. Nếu bạn vừa trải qua một kết thúc khó khăn, hãy tin rằng chương tồi tệ nhất đã khép lại. Bình minh trong lá bài này không phải trang trí — nó là lời hứa.',
 'The Ten of Swords carries a paradoxical comfort: once you hit bottom, the only way is up. If you have just been through a hard ending, trust that the worst chapter has closed. The sunrise in this card is not decoration — it is a promise.',
 'rws/ten_of_swords.jpg'),
(61, 'page_of_swords', 'Tiểu Đồng Kiếm', 'Page of Swords',
 'Trí tò mò sắc bén, khát khao học hỏi và sự cảnh giác tinh nhanh. Một tâm trí trẻ trung đang sẵn sàng khám phá sự thật.',
 'Sharp curiosity, a thirst for learning, and quick vigilance. A young mind ready to uncover the truth.',
 'Lời nói vội vàng, chuyện phiếm gây hại, hoặc năng lượng trí tuệ bị phân tán không mục đích.',
 'Hasty words, harmful gossip, or mental energy scattered without purpose.',
 'Tiểu Đồng Kiếm khơi dậy sự ham học trong bạn. Hôm nay, hãy đặt nhiều câu hỏi hơn là đưa ra kết luận — về công việc, về con người, về chính mình. Một tâm trí tò mò và cởi mở sẽ nhìn thấy những điều mà sự vội vàng bỏ lỡ.',
 'The Page of Swords awakens your love of learning. Today, ask more questions than you draw conclusions — about work, people, and yourself. A curious, open mind sees what haste overlooks.',
 'rws/page_of_swords.jpg'),
(62, 'knight_of_swords', 'Hiệp Sĩ Kiếm', 'Knight of Swords',
 'Hành động quyết liệt, tham vọng và tốc độ của tư duy. Khi mục tiêu đã rõ, không gì cản được bạn.',
 'Decisive action, ambition, and speed of thought. Once the goal is clear, nothing stands in your way.',
 'Sự hấp tấp, hung hăng trong lời nói, hoặc lao đi quá nhanh mà chưa nhìn rõ đường.',
 'Recklessness, aggressive words, or charging ahead too fast to see the road clearly.',
 'Hiệp Sĩ Kiếm mang năng lượng của sự quyết đoán. Hôm nay là ngày tốt để xử lý dứt điểm việc bạn đã trì hoãn — nhưng trước khi lao đi, hãy dành một phút kiểm tra hướng. Tốc độ chỉ có giá trị khi đi đúng đường.',
 'The Knight of Swords carries the energy of decisiveness. Today is a good day to finally tackle what you''ve been putting off — but before charging ahead, take one minute to check your direction. Speed only matters on the right road.',
 'rws/knight_of_swords.jpg'),
(63, 'queen_of_swords', 'Hoàng Hậu Kiếm', 'Queen of Swords',
 'Sự sáng suốt, độc lập và thẳng thắn đầy nhân hậu. Bạn nhìn thấu vấn đề mà không để cảm xúc làm mờ phán đoán.',
 'Clear judgment, independence, and honest candor with kindness. You see through matters without letting emotion cloud you.',
 'Sự lạnh lùng, cay nghiệt, hoặc dùng lý trí như tấm khiên che giấu tổn thương.',
 'Coldness, bitterness, or using intellect as a shield to hide old wounds.',
 'Hoàng Hậu Kiếm mời bạn nhìn mọi việc hôm nay bằng sự sáng suốt không thiên vị. Hãy nói sự thật khi cần, nhưng nói bằng sự tử tế. Ranh giới rõ ràng và trái tim nhân hậu có thể — và nên — cùng tồn tại.',
 'The Queen of Swords invites you to see today''s matters with unbiased clarity. Speak the truth when needed, but speak it with kindness. Clear boundaries and a warm heart can — and should — coexist.',
 'rws/queen_of_swords.jpg'),
(64, 'king_of_swords', 'Vua Kiếm', 'King of Swords',
 'Uy quyền trí tuệ, sự công minh và quyết định dựa trên lý lẽ vững chắc. Bạn có đủ sáng suốt để phân xử điều đúng đắn.',
 'Intellectual authority, fairness, and decisions grounded in solid reason. You have the clarity to judge what is right.',
 'Sự lạm dụng lý lẽ, phán xét khắc nghiệt, hoặc trí tuệ thiếu vắng lòng trắc ẩn.',
 'Misused logic, harsh judgment, or intellect without compassion.',
 'Vua Kiếm mời bạn đưa ra quyết định hôm nay bằng cái đầu lạnh và chuẩn mực rõ ràng. Trước lựa chọn khó, hãy tự hỏi: nếu gạt cảm tính sang một bên, đâu là điều đúng đắn nhất? Sự công minh của bạn sẽ được người khác tôn trọng.',
 'The King of Swords invites you to decide with a cool head and clear principles today. Before a hard choice, ask: setting feelings aside, what is the fairest course? Your integrity will earn others'' respect.',
 'rws/king_of_swords.jpg'),
(65, 'ace_of_pentacles', 'Át Tiền', 'Ace of Pentacles',
 'Cơ hội mới về tài chính hoặc sự nghiệp, hạt giống của thịnh vượng. Một nền tảng vững chắc đang được trao vào tay bạn.',
 'A new financial or career opportunity — a seed of prosperity. A solid foundation is being placed in your hands.',
 'Cơ hội bị bỏ lỡ, kế hoạch tài chính thiếu chắc chắn, hoặc quá bám víu vào vật chất.',
 'A missed opportunity, shaky financial plans, or clinging too tightly to material things.',
 'Át Tiền mang đến hạt giống của sự thịnh vượng. Hôm nay, hãy để ý những cơ hội thiết thực quanh mình — một lời đề nghị, một ý tưởng kiếm thêm, một thói quen tốt cho sức khỏe. Hạt giống nhỏ được gieo hôm nay có thể trở thành mùa vụ của ngày mai.',
 'The Ace of Pentacles brings a seed of prosperity. Today, watch for practical opportunities around you — an offer, an income idea, a healthy new habit. A small seed planted today can become tomorrow''s harvest.',
 'rws/ace_of_pentacles.jpg'),
(66, 'two_of_pentacles', '2 Tiền', 'Two of Pentacles',
 'Sự cân bằng linh hoạt giữa nhiều ưu tiên, khả năng thích ứng với thay đổi. Bạn đang tung hứng khéo léo hơn mình nghĩ.',
 'Flexible balance between competing priorities and adapting to change. You are juggling more gracefully than you think.',
 'Sự quá tải, mất cân bằng giữa các trách nhiệm, hoặc cần buông bớt để giữ nhịp sống.',
 'Overload, imbalance between responsibilities, or the need to drop something to keep your rhythm.',
 '2 Tiền ghi nhận rằng bạn đang xoay xở giữa nhiều vai trò cùng lúc. Hôm nay, thay vì cố làm tất cả thật hoàn hảo, hãy chọn nhịp điệu phù hợp với mình. Cân bằng không phải là đứng yên — đó là chuyển động uyển chuyển theo dòng chảy.',
 'The Two of Pentacles honors how you juggle many roles at once. Today, rather than doing everything perfectly, find a rhythm that suits you. Balance is not standing still — it is moving gracefully with the flow.',
 'rws/two_of_pentacles.jpg'),
(67, 'three_of_pentacles', '3 Tiền', 'Three of Pentacles',
 'Sự hợp tác, tay nghề được công nhận và thành quả từ làm việc nhóm. Mỗi người góp một viên gạch cho công trình chung.',
 'Collaboration, recognized craftsmanship, and the fruits of teamwork. Everyone lays a brick in the shared work.',
 'Sự thiếu phối hợp, làm việc rời rạc, hoặc tay nghề chưa được trân trọng đúng mức.',
 'Poor coordination, working in silos, or skills not yet properly valued.',
 '3 Tiền nhắc rằng những công trình đẹp nhất đều được xây bởi nhiều bàn tay. Hôm nay, đừng ngại nhờ hỗ trợ hoặc chia sẻ chuyên môn của mình với người khác. Khi mỗi người góp phần giỏi nhất của họ, kết quả sẽ vượt xa tổng của từng phần.',
 'The Three of Pentacles reminds you that the finest structures are built by many hands. Today, don''t hesitate to ask for support or share your expertise. When everyone contributes their best, the result exceeds the sum of its parts.',
 'rws/three_of_pentacles.jpg'),
(68, 'four_of_pentacles', '4 Tiền', 'Four of Pentacles',
 'Sự ổn định, tích lũy và nhu cầu an toàn. Nhưng nắm giữ quá chặt có thể khiến bạn không còn tay để đón nhận điều mới.',
 'Stability, saving, and the need for security. Yet holding on too tightly leaves no hand free to receive.',
 'Sự buông bỏ kiểm soát, chi tiêu hào phóng hơn, hoặc nỗi sợ mất mát đang dần được nới lỏng.',
 'Loosening control, giving more freely, or a fear of loss beginning to ease.',
 '4 Tiền hỏi bạn: điều gì bạn đang giữ chặt đến mức nó bắt đầu giữ ngược lại bạn? Sự an toàn là chính đáng, nhưng hôm nay hãy thử mở lòng một chút — chia sẻ, chi tiêu cho điều xứng đáng, hay đơn giản là bớt lo xa. Dòng chảy chỉ đến khi tay ta mở.',
 'The Four of Pentacles asks: what are you gripping so tightly that it has started gripping you back? Security matters, but today try opening up a little — share, spend on what''s worthwhile, or simply worry less. Flow only comes to open hands.',
 'rws/four_of_pentacles.jpg'),
(69, 'five_of_pentacles', '5 Tiền', 'Five of Pentacles',
 'Giai đoạn khó khăn về vật chất hoặc tinh thần, cảm giác bị bỏ lại ngoài lề. Nhưng sự giúp đỡ ở gần hơn bạn nghĩ.',
 'A time of material or emotional hardship and feeling left out in the cold. Yet help is closer than you think.',
 'Sự phục hồi sau giai đoạn khó khăn, cánh cửa hỗ trợ mở ra, hoặc tìm lại niềm tin sau mất mát.',
 'Recovery after hardship, doors of support opening, or faith returning after loss.',
 '5 Tiền thừa nhận rằng có những giai đoạn thật sự chật vật. Nhưng lá bài cũng nhắc: ánh sáng ấm áp vẫn tỏa ra từ ô cửa ngay bên cạnh — đừng ngại gõ cửa. Hôm nay, hãy cho phép mình nhận sự giúp đỡ; điều đó không làm bạn yếu đuối đi chút nào.',
 'The Five of Pentacles admits that some seasons are genuinely hard. But it also reminds you: warm light glows from a window nearby — don''t be afraid to knock. Today, allow yourself to receive help; it takes nothing away from your strength.',
 'rws/five_of_pentacles.jpg'),
(70, 'six_of_pentacles', '6 Tiền', 'Six of Pentacles',
 'Sự hào phóng, cho và nhận cân bằng. Dòng chảy vật chất lành mạnh khi đi qua bàn tay rộng mở.',
 'Generosity and a healthy balance of giving and receiving. Abundance flows well through open hands.',
 'Sự cho đi kèm điều kiện, nợ nần, hoặc mất cân bằng giữa người cho và người nhận.',
 'Giving with strings attached, debt, or an imbalance between giver and receiver.',
 '6 Tiền nói về vòng tuần hoàn của sự cho và nhận. Hôm nay, hãy tìm một cách nhỏ để sẻ chia — thời gian, kiến thức, hay một sự giúp đỡ thầm lặng. Và nếu bạn đang là người cần nhận, hãy nhận với lòng biết ơn thay vì ngại ngùng; đó cũng là một phần của dòng chảy.',
 'The Six of Pentacles speaks of the cycle of giving and receiving. Today, find one small way to share — time, knowledge, or quiet help. And if you are the one in need, receive with gratitude rather than embarrassment; that too is part of the flow.',
 'rws/six_of_pentacles.jpg'),
(71, 'seven_of_pentacles', '7 Tiền', 'Seven of Pentacles',
 'Sự kiên nhẫn chờ mùa vụ, đánh giá lại thành quả đầu tư. Những gì bạn vun trồng đang lớn lên, dù mắt thường khó thấy.',
 'Patience before the harvest and taking stock of your investments. What you planted is growing, even if it''s hard to see.',
 'Sự sốt ruột, công sức đặt sai chỗ, hoặc cần điều chỉnh hướng đầu tư thời gian và tâm huyết.',
 'Impatience, effort placed in the wrong soil, or the need to redirect your time and energy.',
 '7 Tiền mời bạn dừng lại và đánh giá khu vườn của mình. Điều gì bạn đã đầu tư đang thực sự lớn lên, và điều gì chỉ đang rút cạn công sức? Hôm nay, hãy kiên nhẫn với những gì đáng giá — và đủ dũng cảm để ngừng tưới cho những gì không còn.',
 'The Seven of Pentacles invites you to pause and survey your garden. Which of your investments is truly growing, and which merely drains you? Today, be patient with what is worthwhile — and brave enough to stop watering what is not.',
 'rws/seven_of_pentacles.jpg'),
(72, 'eight_of_pentacles', '8 Tiền', 'Eight of Pentacles',
 'Sự chuyên tâm rèn luyện, tinh thần cầu tiến và con đường đến sự tinh thông. Mỗi nhát đục hôm nay là một bước gần hơn tới tay nghề bậc thầy.',
 'Diligent practice, dedication, and the road to mastery. Every careful stroke today brings you closer to true craftsmanship.',
 'Sự cầu toàn quá mức, làm việc thiếu tâm huyết, hoặc lặp lại máy móc mà quên mất mục đích.',
 'Excessive perfectionism, half-hearted work, or mechanical repetition that has lost its purpose.',
 '8 Tiền tôn vinh giá trị của sự chuyên tâm. Hôm nay, hãy chọn một kỹ năng bạn muốn giỏi hơn và dành cho nó một khoảng thời gian tập trung trọn vẹn. Sự tinh thông không đến từ những cú nhảy vọt, mà từ những nhát đục đều đặn mỗi ngày.',
 'The Eight of Pentacles honors the value of devoted practice. Today, choose one skill you want to sharpen and give it a stretch of undivided focus. Mastery comes not from great leaps but from steady strokes, day after day.',
 'rws/eight_of_pentacles.jpg'),
(73, 'nine_of_pentacles', '9 Tiền', 'Nine of Pentacles',
 'Sự độc lập, thành quả tự thân và niềm vui tận hưởng những gì mình gây dựng. Bạn xứng đáng với khu vườn này.',
 'Independence, self-made success, and the pleasure of enjoying what you built. You have earned this garden.',
 'Sự phụ thuộc tài chính, làm việc quá sức quên tận hưởng, hoặc giá trị bản thân gắn chặt vào vật chất.',
 'Financial dependence, overworking without enjoying life, or self-worth tied too tightly to possessions.',
 '9 Tiền mời bạn nhìn lại những gì mình đã tự tay gây dựng — sự nghiệp, kỹ năng, hay đơn giản là cuộc sống bạn đang có. Hôm nay, hãy tận hưởng thành quả ấy mà không cảm thấy có lỗi. Độc lập là món quà bạn đã tự tặng mình bằng bao nỗ lực.',
 'The Nine of Pentacles invites you to look at what you have built with your own hands — a career, a skill, or simply the life you lead. Today, enjoy those fruits without guilt. Independence is a gift you gave yourself through years of effort.',
 'rws/nine_of_pentacles.jpg'),
(74, 'ten_of_pentacles', '10 Tiền', 'Ten of Pentacles',
 'Sự thịnh vượng bền vững, di sản và nền tảng gia đình vững chắc. Những gì bạn xây hôm nay sẽ che chở cho nhiều thế hệ.',
 'Lasting wealth, legacy, and strong family foundations. What you build today will shelter generations.',
 'Bất ổn tài chính gia đình, tranh chấp tài sản, hoặc thành công vật chất thiếu vắng sự gắn kết.',
 'Family financial instability, disputes over assets, or material success without real connection.',
 '10 Tiền nói về những giá trị bền lâu hơn một ngày, một tháng. Hôm nay, hãy làm một điều nhỏ cho nền móng dài hạn của bạn — tiết kiệm một khoản, vun đắp một mối quan hệ gia đình, hay truyền lại một điều hay cho người đi sau. Di sản được xây từ những viên gạch như thế.',
 'The Ten of Pentacles speaks of values that outlast a day or a month. Today, do one small thing for your long-term foundation — set aside some savings, tend a family bond, or pass on something valuable to someone younger. Legacies are built from bricks like these.',
 'rws/ten_of_pentacles.jpg'),
(75, 'page_of_pentacles', 'Tiểu Đồng Tiền', 'Page of Pentacles',
 'Tinh thần ham học hỏi, cơ hội mới về học tập hoặc sự nghiệp. Một ước mơ thực tế đang bắt đầu thành hình.',
 'An eager student''s spirit and new opportunities in study or career. A practical dream is beginning to take shape.',
 'Sự trì hoãn, thiếu tập trung vào mục tiêu, hoặc ước mơ mãi nằm trên giấy vì chưa hành động.',
 'Procrastination, losing focus on goals, or dreams staying on paper for lack of action.',
 'Tiểu Đồng Tiền mang đến tinh thần của người học trò chăm chỉ. Hôm nay, hãy đầu tư vào chính mình — đọc vài trang sách, học một điều mới, hay lên kế hoạch cho mục tiêu bạn ấp ủ. Mỗi bước học hỏi nhỏ đều là một đồng vốn cho tương lai.',
 'The Page of Pentacles brings the spirit of a devoted student. Today, invest in yourself — read a few pages, learn something new, or plan toward a cherished goal. Every small step of learning is capital for your future.',
 'rws/page_of_pentacles.jpg'),
(76, 'knight_of_pentacles', 'Hiệp Sĩ Tiền', 'Knight of Pentacles',
 'Sự cần mẫn, đáng tin cậy và tiến bước đều đặn. Không nhanh nhất, nhưng chắc chắn sẽ đến đích.',
 'Diligence, reliability, and steady progress. Not the fastest, but certain to arrive.',
 'Sự trì trệ, nhàm chán vì lối mòn, hoặc quá thận trọng đến mức bỏ lỡ cơ hội.',
 'Stagnation, boredom from routine, or caution so excessive that opportunities slip by.',
 'Hiệp Sĩ Tiền nhắc rằng sự bền bỉ thầm lặng cũng là một dạng sức mạnh. Hôm nay, hãy làm tốt những việc thường nhật của bạn — từng việc một, cẩn thận và trọn vẹn. Những nỗ lực đều đặn không phô trương chính là thứ xây nên kết quả bền vững nhất.',
 'The Knight of Pentacles reminds you that quiet persistence is its own kind of power. Today, do your everyday tasks well — one at a time, with care and completeness. Steady, unglamorous effort is what builds the most lasting results.',
 'rws/knight_of_pentacles.jpg'),
(77, 'queen_of_pentacles', 'Hoàng Hậu Tiền', 'Queen of Pentacles',
 'Sự đảm đang, thực tế và ấm áp. Bạn biết cách chăm lo cho người khác mà vẫn giữ cuộc sống của mình sung túc, vững vàng.',
 'Practical warmth and nurturing capability. You care for others while keeping your own life abundant and grounded.',
 'Sự mất cân bằng giữa công việc và gia đình, chăm lo người khác mà bỏ quên bản thân, hoặc lo âu về tài chính.',
 'Work-life imbalance, caring for everyone but yourself, or anxiety about material security.',
 'Hoàng Hậu Tiền là hiện thân của sự chăm sóc thiết thực. Hôm nay, hãy chăm lo cho bản thân và người thân bằng những điều cụ thể — một bữa ăn tử tế, một không gian gọn gàng, một khoản chi tiêu hợp lý. Sự ấm áp thể hiện qua hành động luôn có sức nặng hơn lời nói.',
 'The Queen of Pentacles embodies practical care. Today, look after yourself and your loved ones in concrete ways — a proper meal, a tidy space, a sensible budget. Warmth expressed through action always carries more weight than words.',
 'rws/queen_of_pentacles.jpg'),
(78, 'king_of_pentacles', 'Vua Tiền', 'King of Pentacles',
 'Sự thành đạt, vững vàng về vật chất và tấm lòng rộng rãi của người đã gây dựng thành công. Bạn là chỗ dựa đáng tin cậy.',
 'Accomplishment, material mastery, and the generosity of one who has built success. You are a rock others can lean on.',
 'Sự tham lam, cố chấp với vật chất, hoặc dùng tiền bạc và địa vị để khẳng định giá trị bản thân.',
 'Greed, stubborn materialism, or using wealth and status to prove your worth.',
 'Vua Tiền nói về sự vững vàng được xây dựng qua thời gian. Hôm nay, hãy đưa ra các quyết định — nhất là về tiền bạc và công việc — với tầm nhìn dài hạn và sự điềm tĩnh của người làm chủ. Thành công thật sự không chỉ là có nhiều, mà là đủ vững để sẻ chia.',
 'The King of Pentacles speaks of stability built over time. Today, make your decisions — especially about money and work — with a long view and the calm of someone in command. True success is not just having much, but being steady enough to share.',
 'rws/king_of_pentacles.jpg');
